-- mcit_campaigns  <-  db.mcit.campaigns
create table public.mcit_campaigns (
  id text primary key,
  pos integer not null default 0,
  doc json not null,
  owner text generated always as (doc->>'owner') stored,
  project text generated always as (doc->>'project') stored,
  created_by text generated always as (doc->>'createdBy') stored,
  updated_at timestamptz not null default now(),
  updated_by uuid,
  constraint mcit_campaigns_id_matches_doc check (doc->>'id' is null or doc->>'id' = id)
);
create index mcit_campaigns_owner_idx on public.mcit_campaigns (owner);
create index mcit_campaigns_project_idx on public.mcit_campaigns (project);
create index mcit_campaigns_created_by_idx on public.mcit_campaigns (created_by);
create trigger mcit_campaigns_touch before update on public.mcit_campaigns for each row execute function app.touch();
alter table public.mcit_campaigns enable row level security;
revoke all on public.mcit_campaigns from anon, authenticated;
grant select, insert, update, delete on public.mcit_campaigns to service_role;

